@import "@fontsource-variable/inter";
@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource-variable/newsreader/opsz-italic.css";

/* Light sibling: ivory paper #f6f5f1, near-black ink, warm grey secondary text, white cards
   with a sand hairline (#e4e2dc, a border colour the original keeps for its light pages),
   near-black pills, and a deeper gold so figures stay legible on paper. */
:root {
  --background: #f6f5f1;
  --foreground: #09090b;
  --card: #ffffff;
  --card-foreground: #09090b;
  --popover: #ffffff;
  --popover-foreground: #09090b;
  --primary: #09090b;
  --primary-foreground: #ffffff;
  --secondary: #ecebe6;
  --secondary-foreground: #09090b;
  --muted: #eeede8;
  --muted-foreground: #5e616e;
  --accent: #e4e2dc;
  --accent-foreground: #09090b;
  --destructive: #d9363e;
  --destructive-foreground: #ffffff;
  --border: #e4e2dc;
  --input: #d4d0c8;
  --ring: #77798a;
  --highlight: #8c6f34;
  --highlight-foreground: #ffffff;
  --glow: #c27a2c;
  --chart-1: #5b67d8;
  --chart-2: #23a26d;
  --chart-3: #8c6f34;
  --chart-4: #c27a2c;
  --chart-5: #5e616e;
  --sidebar: #eeede8;
  --sidebar-foreground: #09090b;
  --sidebar-primary: #09090b;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e4e2dc;
  --sidebar-accent-foreground: #09090b;
  --sidebar-border: #e4e2dc;
  --sidebar-ring: #77798a;

  --typeface-body: "Inter Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Newsreader Variable", "Times New Roman", Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* 10px cards (12px video tiles = rounded-xl, 8px thumbs = rounded-md) */
  --radius: 0.625rem;
  /* the 1152px column inside 20px gutters */
  --page-width: 74.5rem;
  --page-gutter: 1.25rem;
  /* phones; blocks double it at lg for the original's ~210px section tops */
  --section-y: 6.5rem;
}

/* Dark (faithful): cool near-black #040406, slate cards #101115, hairlines #1c1d22, white ink
   and white pills, cool greys #9194a1 for secondary text, brushed gold #b89a5e figures over an
   amber #cd8939 glow. */
.dark {
  --background: #040406;
  --foreground: #ffffff;
  --card: #0f1013;
  --card-foreground: #ffffff;
  --popover: #0b0c0e;
  --popover-foreground: #ffffff;
  --primary: #ffffff;
  --primary-foreground: #09090b;
  --secondary: #1c1d22;
  --secondary-foreground: #ffffff;
  --muted: #18181b;
  --muted-foreground: #9194a1;
  --accent: #2e3038;
  --accent-foreground: #ffffff;
  --destructive: #f87171;
  --destructive-foreground: #ffffff;
  --border: #1c1d22;
  --input: #464853;
  --ring: #c7c9d1;
  --highlight: #b89a5e;
  --highlight-foreground: #09090b;
  --glow: #cd8939;
  --chart-1: #6b74e0;
  --chart-2: #2fbf7f;
  --chart-3: #b89a5e;
  --chart-4: #cd8939;
  --chart-5: #9194a1;
  --sidebar: #0b0c0e;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #ffffff;
  --sidebar-primary-foreground: #09090b;
  --sidebar-accent: #1c1d22;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #1c1d22;
  --sidebar-ring: #c7c9d1;
}
